-- =============================================================================
-- recharge_dump_raw.recharge_id is "GENERATED ALWAYS AS IDENTITY", which
-- means Postgres rejects any INSERT/COPY that supplies its own value for
-- that column (you'd need "OVERRIDING SYSTEM VALUE", which the COPY
-- statement does not support).
--
-- The loader needs to reserve recharge_id values up-front (via nextval) so
-- it can use the very same ids when writing the exploded rows into
-- recharge_dump_balances, in the same transaction as the recharge_dump_raw
-- insert. Switching to "GENERATED BY DEFAULT AS IDENTITY" allows that:
-- explicit values are accepted, and the underlying sequence is left exactly
-- as-is (same name, same current value), so nothing else changes.
--
-- Safe to re-run.
-- =============================================================================
ALTER TABLE recharge_dump_raw
    ALTER COLUMN recharge_id SET GENERATED BY DEFAULT;
